settings.custom_liquid:
{%- assign loox_total = 0 -%}
<div class="loox-ssr-all-reviews" style="display:none">
  {%- for p in collections.all.products -%}
    {%- assign p_count = p.metafields.loox.num_reviews.value | plus: 0 -%}
    {%- assign loox_total = loox_total | plus: p_count -%}
    {%- if p.metafields.loox.reviews != blank -%}
      <div data-product="{{ p.handle }}">
        <h3>{{ p.title | escape }}</h3>
        {{ p.metafields.loox.reviews | replace: 'id="loox-inline-reviews"', 'class="loox-inline-reviews"' }}
      </div>
    {%- endif -%}
  {%- endfor -%}
  <p>{{ loox_total }} verified customer reviews</p>
</div>
